-- seed graphite: сгенерировано tenant:sql, повторный запуск обновляет настройки
on conflict(slug) do update set timezone=excluded.timezone,buffer_minutes=excluded.buffer_minutes,config=excluded.config;
update services set category='Мойка',price_cents=350000,duration_minutes=120 where tenant_id=(select id from tenants where slug='graphite') and name='Комплексная мойка';
update services set category='Салон',price_cents=1200000,duration_minutes=1440 where tenant_id=(select id from tenants where slug='graphite') and name='Химчистка салона';
update services set category='Полировка',price_cents=1800000,duration_minutes=1440 where tenant_id=(select id from tenants where slug='graphite') and name='Полировка кузова';
update services set category='Защита кузова',price_cents=2500000,duration_minutes=2880 where tenant_id=(select id from tenants where slug='graphite') and name='Керамическое покрытие';
